/**
 * The snapshot of the server's tool list shipped with the package (catalogue/instantane.json), generated by
 * `npm run instantane` and never written by hand. It is served only when the Sirenic server cannot be reached
 * at startup; calls are then refused without signing anything. The package reads it, and never writes a file.
 */
import { readFileSync } from "node:fs";
import type { Tool } from "@modelcontextprotocol/sdk/types.js";

export interface Snapshot {
  /** ISO date and time of the tools/list read. */
  generated_at: string;
  /** The MCP endpoint that was read. */
  source: string;
  /** serverInfo of that server. */
  server: { name: string; version: string };
  /** The server's instructions (initialize). */
  instructions?: string;
  /** tools/list, as served (payment parameters included). */
  tools: Tool[];
}

export const SNAPSHOT_URL = new URL("../catalogue/instantane.json", import.meta.url);

export function parseSnapshot(text: string): Snapshot {
  const data = JSON.parse(text) as Partial<Snapshot>;
  if (
    typeof data.generated_at !== "string" ||
    typeof data.source !== "string" ||
    typeof data.server?.version !== "string" ||
    !Array.isArray(data.tools) ||
    data.tools.some((t) => typeof t?.name !== "string")
  ) {
    throw new Error("catalogue/instantane.json is not a tools/list snapshot");
  }
  return data as Snapshot;
}

export function readSnapshot(url: URL = SNAPSHOT_URL): Snapshot {
  return parseSnapshot(readFileSync(url, "utf8"));
}
